def solve_n4_efficient(max_k):
    for k in range(1, max_k + 1):
        k2 = k*k
        k2_7 = 7*k2

        # Find all a in Z^4 such that |a|^2 = k^2
        a_list = []
        # Use a more efficient way to find a
        # a_i can range from -k to k
        for a1 in range(-k, k + 1):
            for a2 in range(-k, k + 1):
                if a1*a1 + a2*a2 > k2: continue
                for a3 in range(-k, k + 1):
                    if a1*a1 + a2*a2 + a3*a3 > k2: continue
                    a4_sq = k2 - (a1*a1 + a2*a2 + a3*a3)
                    a4 = int(a4_sq**0.5)
                    if a4*a4 == a4_sq:
                        a_list.append((a1, a2, a3, a4))
                        if a4 != 0:
                            a_list.append((a1, a2, a3, -a4))

        # Remove duplicates
        a_list = list(set(a_list))

        if not a_list:
            continue

        # Now for each a, find b in Z^4 such that |b|^2 = 7k^2 and a.b = 0
        # Since we only need to know if it exists, let's try b more efficiently.
        # b_i can range from -sqrt(7k^2) to sqrt(7k^2)
        max_b = int((k2_7)**0.5) + 1

        for a in a_list:
            # We want to find b1, b2, b3, b4 such that:
            # b1^2 + b2^2 + b3^2 + b4^2 = 7k^2
            # a1*b1 + a2*b2 + a3*b3 + a4*b4 = 0
            # Let's iterate over b1, b2, b3 and find b4.
            for b1 in range(-max_b, max_b + 1):
                for b2 in range(-max_b, max_b + 1):
                    if b1*b1 + b2*b2 > k2_7: continue
                    for b3 in range(-max_b, max_b + 1):
                        if b1*b1 + b2*b2 + b3*b3 > k2_7: continue
                        b4_sq = k2_7 - (b1*b1 + b2*b2 + b3*b3)
                        b4 = int(b4_sq**0.5)
