            # We want b1^2 + b2^2 + b3^2 = 7k^2 and a1*b1 + a2*b2 + a3*b3 = 0
            # We can iterate over b1, b2 and check b3
            max_b = int(math.isqrt(k2_7))
            for b1 in range(-max_b, max_b + 1):
                b1_2 = b1*b1
                for b2 in range(-max_b, max_b + 1):
                    b12_2 = b1_2 + b2*b2
                    if b12_2 > k2_7: continue
                    b3_sq = k2_7 - b12_2
                    b3 = int(math.isqrt(b3_sq))
                    if b3*b3 == b3_sq:
                        if a1*b1 + a2*b2 + a3*b3 == 0:
                            return k, (a1, a2, a3), (b1, b2, b3)
                        if a3 != 0 and a1*b1 + a2*b2 - a3*b3 == 0:
                            return k, (a1, a2, a3), (b1, b2, -b3)
    return None

